import{DURATION,clamp,mix,smooth,timeline,portraitLayout,dragProgress}from'./hero-timeline.js';
import{renderFrame}from'./hero-renderer.js';
const hero=document.querySelector('#home'),track=document.querySelector('.entry-track');
const canvas=document.querySelector('#hero-canvas'),front=document.querySelector('#hero-character');
const ctx=canvas.getContext('2d'),fg=front.getContext('2d');
const play=document.querySelector('#scene-play'),range=document.querySelector('#scene-scrub');
const timeLabel=document.querySelector('#scene-time'),chapter=document.querySelector('#scene-chapter'),caption=document.querySelector('#scene-caption');
const headlines=['01 / A CLOSER LOOK','02 / THE BIGGER PICTURE','03 / ABHAY SHUKLA'];
const captions=['Every system starts with a different way of seeing.','AI engineer. Full-stack builder. A world of possibilities.','From the first question to the final deployment.'];
let width=1,height=1,dpr=1,progress=0,scroll=0,playing=true,ready=false,off=document.body.classList.contains('motion-off'),visible=true,last=0,elapsed=0,drawn=0;
let pointer={x:0,y:0,tx:0,ty:0},drag=null,waveUntil=0;
const images={};let loaded=0;const image=src=>new Promise((resolve,reject)=>{const i=new Image();i.onload=()=>{loaded++;document.querySelector('#scene-loaded').textContent=String(Math.round(loaded/6*100)).padStart(2,'0');resolve(i)};i.onerror=reject;i.src=src});
function resize(){const r=hero.getBoundingClientRect();width=Math.max(1,r.width);height=Math.max(1,r.height);dpr=Math.min(devicePixelRatio||1,1.5);for(const c of[canvas,front]){c.width=Math.round(width*dpr);c.height=Math.round(height*dpr);c.style.width=width+'px';c.style.height=height+'px'}drawn=0;if(ready)render()}
new ResizeObserver(resize).observe(hero);
function setPlaying(value){playing=value&&!off;play.textContent=playing?'Pause':'Play';play.setAttribute('aria-label',playing?'Pause cinematic intro':'Play cinematic intro');play.setAttribute('aria-pressed',String(playing))}
function seek(value){progress=clamp(value);setPlaying(false);render()}
function replay(){if(off)return;progress=0;elapsed=0;waveUntil=0;setPlaying(true);if(window.scrollY>track.offsetTop+40)window.scrollTo({top:track.offsetTop,behavior:'smooth'});render()}
play.addEventListener('click',()=>{if(progress>=1&& !playing)replay();else setPlaying(!playing)});range.addEventListener('input',()=>seek(Number(range.value)/1000));document.querySelector('#scene-replay').addEventListener('click',replay);window.addEventListener('hero-replay',replay);
document.querySelectorAll('[data-scene-progress]').forEach(b=>b.addEventListener('click',()=>seek(Number(b.dataset.sceneProgress))));
canvas.addEventListener('pointerdown',e=>{if(off)return;drag={id:e.pointerId,x:e.clientX,y:e.clientY,start:progress,moved:false};canvas.setPointerCapture(e.pointerId)});
canvas.addEventListener('pointermove',e=>{const r=canvas.getBoundingClientRect();pointer.tx=(e.clientX-r.left)/width-.5;pointer.ty=(e.clientY-r.top)/height-.5;if(drag&&drag.id===e.pointerId){const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.abs(dx)>8&&Math.abs(dx)>Math.abs(dy)){drag.moved=true;seek(dragProgress(drag.start,dx,width))}}});
function release(e){if(!drag||drag.id!==e.pointerId)return;if(!drag.moved&&ready){waveUntil=elapsed+2.4;progress=Math.max(progress,.9)}if(canvas.hasPointerCapture(e.pointerId))canvas.releasePointerCapture(e.pointerId);drag=null;render()}
canvas.addEventListener('pointerup',release);canvas.addEventListener('pointercancel',()=>{drag=null});canvas.addEventListener('pointerleave',()=>{pointer.tx=0;pointer.ty=0});
canvas.addEventListener('keydown',e=>{if(off)return;if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();seek(progress+(e.key==='ArrowRight'?.025:-.025))}if(e.key==='Home'){e.preventDefault();seek(0)}if(e.key==='End'){e.preventDefault();seek(1)}if(e.key===' '){e.preventDefault();setPlaying(!playing)}});
let scrollFrame=false;function updateScroll(){scrollFrame=false;const r=track.getBoundingClientRect();scroll=clamp(-r.top/Math.max(1,track.offsetHeight-height));if(scroll>.015&&!off){progress=Math.max(progress,smooth(0,.35,scroll));setPlaying(false)}render()}
window.addEventListener('scroll',()=>{if(!scrollFrame){scrollFrame=true;requestAnimationFrame(updateScroll)}},{passive:true});
window.addEventListener('motionchange',e=>{off=e.detail;if(off){progress=1;setPlaying(false)}else setPlaying(true);render()});
new IntersectionObserver(entries=>{visible=entries[0].isIntersecting;last=0}).observe(hero);
function poseFor(state){if(off)return 2;if(!playing)return state.pose;if(elapsed<waveUntil)return 3;if(progress<1)return state.pose;const cycle=elapsed%12;return cycle<5?(cycle%3.2<.14?1:0):cycle<9?2:3}

let lastChapter=-1;function render(){if(!ready)return;const state=timeline(progress,off);renderFrame(ctx,fg,images,{width,height,dpr,scroll,elapsed,pointer,off,state,pose:poseFor(state)});const about=smooth(.08,.75,scroll),title=state.title*(1-smooth(.02,.45,scroll));hero.style.setProperty('--reveal',String(state.title));hero.style.setProperty('--title-visible',String(title));hero.style.setProperty('--about-visible',String(about));hero.style.setProperty('--about-shift',((1-about)*38)+'px');hero.style.setProperty('--copy-visible',String(state.title*(1-about)));hero.classList.toggle('scene-about',about>.65);document.querySelector('.hero-about').inert=about<.1;document.querySelector('.hero-copy').inert=state.title*(1-about)<.1;hero.classList.toggle('scene-interactive',state.progress>.6);if(state.chapter!==lastChapter){chapter.textContent=headlines[state.chapter];caption.textContent=captions[state.chapter];lastChapter=state.chapter}range.value=String(Math.round(state.progress*1000));range.setAttribute('aria-valuetext',`${Math.round(state.progress*100)} percent, ${headlines[state.chapter].slice(5)}`);const sec=String(Math.round(state.progress*DURATION)).padStart(2,'0');timeLabel.textContent='00:'+sec+' / 00:12'}
function frame(now){requestAnimationFrame(frame);if(!ready||!visible||document.hidden||off||!playing){last=0;return}if(!last)last=now;const dt=Math.min((now-last)/1000,.08);last=now;if(!off&&playing){elapsed+=dt;pointer.x+=(pointer.tx-pointer.x)*.04;pointer.y+=(pointer.ty-pointer.y)*.04;if(playing){progress=clamp(progress+dt/DURATION);}}if(now-drawn>=1000/30){render();drawn=now}}
Promise.all([image('assets/studio-plate.webp'),image('assets/character-eyes.webp'),...[0,1,2,3].map(i=>image('assets/character-'+i+'.webp'))]).then(([plate,eyes,...frames])=>{images.plate=plate;images.eyes=eyes;images.frames=frames;ready=true;hero.classList.add('scene-ready');if(off){progress=1;setPlaying(false)}resize();render();requestAnimationFrame(frame)}).catch(()=>{hero.classList.add('scene-unavailable');setPlaying(false);chapter.textContent='ABHAY SHUKLA';caption.textContent='AI engineer. Full-stack builder.';hero.style.setProperty('--reveal','1');hero.style.setProperty('--title-visible','1');hero.style.setProperty('--copy-visible','1');document.querySelector('.cinema-controls').hidden=true});
resize();setPlaying(!off);
